#!/bin/bash
export $(grep -v '^#' .env | xargs)
docker run --rm --network bdc-net -v $(pwd):/workspace -v $(pwd)/../llm-wiki-assistant/shared-pkg:/shared-pkg -w /workspace -e PYTHONPATH=/workspace:/shared-pkg:/workspace/metrics-worker:/workspace/metrics-api -e GITHUB_PAT=${GITHUB_PAT} -e GITHUB_TOKEN=${GITHUB_PAT} -e MAPEO_API_TOKEN=8f3b2a9d8f3b2a9d8f3b2a9d8f3b2a9d -e ENABLE_DEMO_AUTH=true -e MAPEO_API_URL=http://127.0.0.1:8001 -e DATABASE_URL=postgresql://mapeo_user:mapeo_db_pass@postgres:5432/mapeo_test_db -e E2E_TEST_FORK_URL=${E2E_TEST_FORK_URL:-https://github.com/julia8873/e2e-test-repo.git} moodle-matrix-dev-mapeo-api sh -c "apt-get update && apt-get install -y git && cd /code && alembic upgrade head && python -c \"import psycopg2, os; conn=psycopg2.connect(os.environ['DATABASE_URL']); cur=conn.cursor(); cur.execute('CREATE SCHEMA IF NOT EXISTS metrics;'); conn.commit()\" && cd /workspace/metrics-api && alembic upgrade head && cd /code && (uvicorn app.main:app --port 8001 --host 127.0.0.1 >/workspace/uvicorn.log 2>&1 &) && sleep 5 && cd /workspace && python scripts/run_true_e2e.py"
